import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    p = int(data[1])
    s = list(data[2])

    chars = [chr(ord('a') + i) for i in range(p)]

    def is_palindrome_check(idx, current_s):
        if idx < 1:
            return True
        if current_s[idx] == current_s[idx - 1]:
            return False
        if idx >= 2 and current_s[idx] == current_s[idx - 2]:
            return False
        return True

    i = n - 1
    while i >= 0:
        current_char_idx = ord(s[i]) - ord('a')
        found_next = False

        for next_char_idx in range(current_char_idx + 1, p):
            candidate = chars[next_char_idx]
            s[i] = candidate
            if is_palindrome_check(i, s):
                found_next = True
                break

        if found_next:
            for j in range(i + 1, n):
                for char_idx in range(p):
                    candidate = chars[char_idx]
                    s[j] = candidate
                    if is_palindrome_check(j, s):
                        break
            print("".join(s))
            return
        else:
            i -= 1

    print("NO")

if __name__ == "__main__":
    solve()
